import { Navigate } from "react-router-dom";

const AdminRoute = ({ children }) => {
  const user = JSON.parse(localStorage.getItem("user"));

  // Agar user exist nahi karta
  if (!user) {
    return <Navigate to="/login" replace />;
  }

  // Agar admin nahi hai
  if (user.role !== "admin") {
    return <Navigate to="/login" replace />;
  }

  return children;
};

export default AdminRoute;
